# [LATER-STEP] live_caption_safety.py\n# Check live speech captions for unsafe content using IBM Watson Natural Language\n# Classifier (Guardrails) hosted service.\n\nimport asyncio\nimport json\nimport os\nimport sys\nfrom ibm_watson import NaturalLanguageUnderstandingV1\nfrom ibm_watson.natural_language_understanding_v1 import Features, AnalyticsOptions\nfrom ibm_cloud_sdk_core.authenticators import IAMAuthenticator\n\n# ----------------------------------------------------------\n# Environment configuration\n# ----------------------------------------------------------\nAPIKEY = os.getenv('NLU_APIKEY')\nURL = os.getenv('NLU_URL', 'https://api.us-south.natural-language-understanding.watson.cloud.ibm.com')\nif not APIKEY:\n    print('Set NLU_APIKEY environment variable')\n    sys.exit(1)\nauthenticator = IAMAuthenticator(APIKEY)\nnlu = NaturalLanguageUnderstandingV1(\n    version='2023-08-01',\n    authenticator=authenticator,\n)\nnlu.set_service_url(URL)\n\n# ----------------------------------------------------------\n# Helper: evaluate safety of a text chunk\n# ----------------------------------------------------------\nasync def check_safety(text: str) -> dict:\n    \"\"\"Return NLU response containing toxicity, profanity, etc.\n\n    Returns a dict with keys: 'toxicity', 'profanity', 'insult', 'obscene',\n    'threat', 'identity_hate'.\n    \"\"\"\n    try:\n        response = nlu.analyze(\n            text=text,\n            features=Features(\n                toxicity=AnalyticsOptions(),\n                profanity=AnalyticsOptions(),\n                insult=AnalyticsOptions(),\n                obscene=AnalyticsOptions(),\n                threat=AnalyticsOptions(),\n                identity_hate=AnalyticsOptions(),\n            ),\n        ).get_result()\n        # Extract sentiment scores (simple aggregation)\n        scores = {}\n        for category in ['toxicity', 'profanity', 'insult', 'obscene', 'threat', 'identity_hate']:\n            score = next((c['score'] for c in response.get('categories', []) if c['name'] == category), None)\n            scores[category] = score\n        return scores\n    except Exception as e:\n        print('Safety analysis error:', e)\n        return {}\n\n# ----------------------------------------------------------\n# Integration with live caption stream\n# ----------------------------------------------------------\n# Assume a generator `caption_generator()` that yields dicts with a 'transcript' key.\n# For demo purposes a placeholder generator is used.\n# ----------------------------------------------------------\nasync def caption_generator():\n    # Simulated live chunks\n    for txt in ['This is a safe sentence.', 'This is hate speech!']:\n        yield {'transcript': txt, 'final': True}\n\n# ----------------------------------------------------------\n# Main loop\n# ----------------------------------------------------------\nasync def main():\n    async for chunk in caption_generator():\n        text = chunk['transcript']\n        print('Caption:', text)\n        safety = await check_safety(text)\n        print('Safety scores:', safety)\n\nif __name__ == '__main__':\n    asyncio.run(main())\n